## Instance method call

```beskid
type Counter {
    i32 value;

    pub unit Increment() {
        value += 1;
    }
}

unit UseCounter() {
    let c = Counter { value = 0 };
    c.Increment();
}
```

## extend type

```beskid
type Point {
    f32 x;
    f32 y;
}

extend type Point {
    pub f32 DistanceTo(Point other) {
        let dx = x - other.x;
        let dy = y - other.y;
        return dx * dx + dy * dy;
    }
}

unit UseExtension() {
    let a = Point { x = 0.0, y = 0.0 };
    let b = Point { x = 3.0, y = 4.0 };
    let d = a.DistanceTo(b);
}
```

